('400001', '4001', 'National Monument (Monas)', 'National Monument (Monas)', 'Indonesia''s 132-metre national monument with a history museum, independence symbolism and an observation platform.', '1-2 hours', 'Morning', '', '', 'DKI Jakarta', 0, 0, '', '', 'Monument/observation ticketed; surrounding square free', 5.0, 4.7, -6.1754, 106.8272, 'National Monument (Monas), DKI Jakarta, Indonesia', 'https://www.indonesia.travel/', 0.95, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'verified', 'Official Indonesia Travel identifies Monas as a core Jakarta landmark. Observation access and ticketing can change.', '2026-10-01'),
('400002', '4001', 'National Museum of Indonesia', 'National Museum of Indonesia', 'National museum presenting archaeology, ethnography, history and material culture from across the Indonesian archipelago.', '1-2 hours', 'Morning', '', '', 'DKI Jakarta', 0, 0, '', '', 'Ticketed museum', 4.9, 4.8, -6.1764, 106.8215, 'National Museum of Indonesia, DKI Jakarta, Indonesia', 'https://www.museumnasional.or.id/', 0.94, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'partial', 'Major national museum; current gallery access and post-renovation hours should be refreshed.', '2026-10-01'),
('400003', '4001', 'Istiqlal Mosque', 'Istiqlal Mosque', 'Southeast Asia''s largest mosque and a major symbol of Indonesian independence and religious life.', '1-2 hours', 'Morning', '', '', 'DKI Jakarta', 0, 0, '', '', 'Free; guided visitor arrangements may apply', 4.9, 4.8, -6.1702, 106.8312, 'Istiqlal Mosque, DKI Jakarta, Indonesia', NULL, 0.94, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'verified', 'Official tourism sources consistently list Istiqlal as a major Jakarta landmark. Visitor access follows prayer and security schedules.', '2026-10-01'),
('400004', '4001', 'Jakarta Cathedral', 'Jakarta Cathedral', 'Neo-Gothic Roman Catholic cathedral standing opposite Istiqlal Mosque in central Jakarta.', '1-2 hours', 'Morning', '', '', 'DKI Jakarta', 0, 0, '', '', 'Free', 4.7, 4.6, -6.1692, 106.8331, 'Jakarta Cathedral, DKI Jakarta, Indonesia', NULL, 0.93, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'verified', 'Historic active cathedral; visitor access follows worship schedule.', '2026-10-01'),
