('400141', '4008', 'Komodo National Park', 'Komodo National Park', 'UNESCO-listed protected archipelago safeguarding Komodo dragons, savanna islands and exceptional marine ecosystems.', '1-2 hours', 'Morning', '', 'SIORA reservation and licensed boat/operator planning required', 'East Nusa Tenggara', 0, 0, '', '', 'WNA park entry Rp250,000 under current national tariff; boat/operator costs separate', 5.0, 5.0, -8.55, 119.48, 'Komodo National Park, East Nusa Tenggara, Indonesia', 'https://www.indonesia.travel/id/id/destination/bali-nusa-tenggara/east-nusa-tenggara/labuan-bajo---komodo-national-park', 0.95, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'verified', 'Official Indonesia Travel states WNA entry Rp250,000 and a maximum quota of 1,000 visitors/day from 1 Apr 2026, with SIORA online reservation required.', '2026-10-01'),
