('400161', '4009', 'Maimun Palace', 'Maimun Palace', 'Historic royal palace of the Deli Sultanate in Medan, blending Malay, Islamic and European design.', '1-2 hours', 'Morning', '', '', 'North Sumatra', 0, 0, '', '', 'Ticketed palace', 4.7, 4.5, 3.5752, 98.6831, 'Maimun Palace, North Sumatra, Indonesia', 'https://www.indonesia.travel/', 0.93, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'verified', 'Official Indonesia Travel features Maimun Palace in Medan itineraries.', '2026-10-01'),
('400162', '4009', 'Great Mosque of Medan', 'Great Mosque of Medan', 'Grand early-20th-century mosque near Maimun Palace, known for its octagonal form and ornate interior.', '1-2 hours', 'Morning', '', '', 'North Sumatra', 0, 0, '', '', 'Free; donations optional', 4.7, 4.6, 3.5753, 98.6878, 'Great Mosque of Medan, North Sumatra, Indonesia', NULL, 0.93, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'verified', 'Identity is established; current operating hours/fees should be refreshed before production.', '2026-10-01'),
('400163', '4009', 'Tjong A Fie Mansion', 'Tjong A Fie Mansion', 'Restored mansion of merchant and community leader Tjong A Fie, showcasing Chinese, Malay and European influences.', '1-2 hours', 'Morning', '', '', 'North Sumatra', 0, 0, '', '', 'Ticketed heritage house', 4.8, 4.8, 3.5852, 98.68, 'Tjong A Fie Mansion, North Sumatra, Indonesia', 'https://www.indonesia.travel/', 0.93, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'verified', 'Official Indonesia Travel itineraries highlight Tjong A Fie Mansion as a major Medan heritage stop.', '2026-10-01'),
('400164', '4009', 'Rahmat International Wildlife Museum & Gallery', 'Rahmat International Wildlife Museum & Gallery', 'Private natural-history collection in Medan displaying taxidermy and wildlife specimens from around the world.', '1-2 hours', 'Morning', '', '', 'North Sumatra', 0, 0, '', '', 'Ticketed museum', 4.2, 4.2, 3.5749, 98.6648, 'Rahmat International Wildlife Museum & Gallery, North Sumatra, Indonesia', NULL, 0.89, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'partial', 'Identity is established; current operating hours/fees should be refreshed before production.', '2026-10-01'),
('400165', '4009', 'Graha Maria Annai Velangkanni', 'Graha Maria Annai Velangkanni', 'Distinctive Catholic Marian shrine in Medan with Indo-Mughal-inspired architecture and pilgrimage significance.', '1-2 hours', 'Morning', '', '', 'North Sumatra', 0, 0, '', '', 'Free / donations optional', 4.4, 4.5, 3.5484, 98.6147, 'Graha Maria Annai Velangkanni, North Sumatra, Indonesia', NULL, 0.9, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'partial', 'Identity is established; current operating hours/fees should be refreshed before production.', '2026-10-01'),
('400166', '4009', 'Merdeka Walk & Lapangan Merdeka', 'Merdeka Walk & Lapangan Merdeka', 'Central civic area in Medan surrounded by heritage buildings, food outlets and transport landmarks.', '1-2 hours', 'Morning', '', '', 'North Sumatra', 0, 0, '', '', 'Free public space; food extra', 4.1, 4.2, 3.5905, 98.6783, 'Merdeka Walk & Lapangan Merdeka, North Sumatra, Indonesia', NULL, 0.88, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'partial', 'Identity is established; current operating hours/fees should be refreshed before production.', '2026-10-01'),
('400167', '4009', 'Lake Toba', 'Lake Toba', 'Vast volcanic caldera lake surrounding Samosir Island and forming the cultural heartland of the Toba Batak people.', '1-2 hours', 'Morning', '', '', 'North Sumatra', 0, 0, '', '', 'Public viewpoints free; ferries/attractions extra', 5.0, 5.0, 2.6845, 98.8756, 'Lake Toba, North Sumatra, Indonesia', 'https://www.indonesia.travel/', 0.95, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'verified', 'Official Indonesia Travel promotes Lake Toba as one of Indonesia''s flagship destinations.', '2026-10-01'),
('400168', '4009', 'Parapat', 'Parapat', 'Lakeside gateway town on the eastern shore of Lake Toba, with ferries to Samosir Island.', '1-2 hours', 'Morning', '', '', 'North Sumatra', 0, 0, '', '', 'Town access free; ferries extra', 4.4, 4.4, 2.6635, 98.9349, 'Parapat, North Sumatra, Indonesia', NULL, 0.9, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'verified', 'Identity is established; current operating hours/fees should be refreshed before production.', '2026-10-01'),
('400169', '4009', 'Samosir Island', 'Samosir Island', 'Large volcanic island within Lake Toba, home to Batak villages, tombs, viewpoints and lakeside resorts.', '1-2 hours', 'Morning', '', '', 'North Sumatra', 0, 0, '', '', 'Island access via ferry; attractions vary', 5.0, 4.9, 2.6, 98.8333, 'Samosir Island, North Sumatra, Indonesia', NULL, 0.95, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'verified', 'Identity is established; current operating hours/fees should be refreshed before production.', '2026-10-01'),
('400170', '4009', 'Tomok Village', 'Tomok Village', 'Popular Samosir village known for Batak royal tombs, traditional houses and souvenir market.', '1-2 hours', 'Morning', '', '', 'North Sumatra', 0, 0, '', '', 'Village/site entry and donations may apply', 4.7, 4.6, 2.6555, 98.8594, 'Tomok Village, North Sumatra, Indonesia', NULL, 0.93, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'partial', 'Identity is established; current operating hours/fees should be refreshed before production.', '2026-10-01'),
('400171', '4009', 'Huta Siallagan', 'Huta Siallagan', 'Historic Batak village in Ambarita with stone chairs, traditional houses and stories of customary law.', '1-2 hours', 'Morning', '', '', 'North Sumatra', 0, 0, '', '', 'Ticketed cultural site', 4.8, 4.8, 2.681, 98.832, 'Huta Siallagan, North Sumatra, Indonesia', 'https://www.indonesia.travel/', 0.93, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'verified', 'Official tourism material regularly includes Ambarita/Huta Siallagan in Lake Toba itineraries.', '2026-10-01'),
('400172', '4009', 'Ambarita Stone Chairs', 'Ambarita Stone Chairs', 'Ancient stone council and judgment seats associated with traditional Batak governance in Ambarita.', '1-2 hours', 'Morning', '', '', 'North Sumatra', 0, 0, '', '', 'Usually covered within Huta Siallagan access', 4.4, 4.5, 2.6811, 98.8319, 'Ambarita Stone Chairs, North Sumatra, Indonesia', NULL, 0.9, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'partial', 'Identity is established; current operating hours/fees should be refreshed before production.', '2026-10-01'),
('400173', '4009', 'Huta Bolon Simanindo Museum', 'Huta Bolon Simanindo Museum', 'Former Batak royal compound and museum in Simanindo with traditional architecture and cultural performances.', '1-2 hours', 'Morning', '', '', 'North Sumatra', 0, 0, '', '', 'Ticketed museum/cultural performance', 4.6, 4.7, 2.7526, 98.7556, 'Huta Bolon Simanindo Museum, North Sumatra, Indonesia', NULL, 0.92, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'partial', 'Identity is established; current operating hours/fees should be refreshed before production.', '2026-10-01'),
