('400175', '4009', 'Sipiso-Piso Waterfall', 'Sipiso-Piso Waterfall', 'Tall waterfall plunging about 120 metres near the northern end of Lake Toba.', '1-2 hours', 'Morning', '', '', 'North Sumatra', 0, 0, '', '', 'Local entry fee', 4.9, 4.8, 2.9162, 98.5232, 'Sipiso-Piso Waterfall, North Sumatra, Indonesia', 'https://www.indonesia.travel/', 0.94, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'verified', 'Official Indonesia Travel Lake Toba itineraries identify Sipiso-Piso as a major viewpoint and waterfall stop.', '2026-10-01'),
