('400181', '4010', 'Losari Beach Promenade', 'Losari Beach Promenade', 'Makassar''s landmark waterfront promenade, popular for sunset, street food and city views.', '1-2 hours', 'Sunset', '', '', 'South Sulawesi', 0, 1, '', '', 'Free public promenade; food extra', 4.7, 4.5, -5.1438, 119.4078, 'Losari Beach Promenade, South Sulawesi, Indonesia', 'https://www.indonesia.travel/', 0.93, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'verified', 'Official Indonesia Travel South Sulawesi page highlights Losari Beach as a key Makassar destination.', '2026-10-01'),
('400182', '4010', 'Fort Rotterdam', 'Fort Rotterdam', 'Well-preserved colonial fort in central Makassar built over an earlier Gowa fortress and associated with regional history.', '1-2 hours', 'Morning', '', '', 'South Sulawesi', 0, 0, '', '', 'Public fort access / museum fees vary', 4.8, 4.7, -5.134, 119.4057, 'Fort Rotterdam, South Sulawesi, Indonesia', 'https://www.indonesia.travel/', 0.93, '2026-10-01 17:45:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 17:45:00', 'verified', 'Official tourism content identifies Fort Rotterdam as a major Makassar heritage site.', '2026-10-01'),
